CREATE TYPE visit_status AS ENUM ('Checked-In', 'Checked-Out', 'Archived');

CREATE TABLE "Users" (user_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL);

CREATE TABLE "Employees" (emp_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID REFERENCES "Users"(user_id), name TEXT NOT NULL, department TEXT NOT NULL, mobile_no TEXT, is_active BOOLEAN DEFAULT TRUE);

CREATE TABLE "Visitors" (visitor_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, mobile TEXT NOT NULL, company TEXT);

CREATE TABLE "VisitHistory" (visit_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), visitor_id UUID REFERENCES "Visitors"(visitor_id), emp_id UUID REFERENCES "Employees"(emp_id), check_in TIMESTAMPTZ NOT NULL DEFAULT NOW(), check_out TIMESTAMPTZ, expected_duration_minutes INT CHECK (expected_duration_minutes <= 480), status visit_status DEFAULT 'Checked-In', photo_url TEXT);

CREATE UNIQUE INDEX idx_unique_active_visitor_mobile ON "VisitHistory" (visitor_id) WHERE (status = 'Checked-In');

CREATE OR REPLACE FUNCTION trg_verify_employee_active() RETURNS TRIGGER AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM "Employees" WHERE emp_id = NEW.emp_id AND is_active = TRUE) THEN
    RAISE EXCEPTION 'Employee is inactive';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER verify_employee_active BEFORE INSERT ON "VisitHistory" FOR EACH ROW EXECUTE FUNCTION trg_verify_employee_active();
